# situ capability map v1
# schema: rrpc_local.situ
# core:   offset size align repr atomic
#
# Core axes are always shown. Any other axis appears only where it has
# been weakened below its strongest value.
#
# Offsets are byte values, or byte:bit where a field does not start on
# a byte boundary. Sizes are bytes unless suffixed with `bit`.
#
# A struct's size is a bare number where it is fixed, `min..max` where
# it is bounded, and `min..` where nothing bounds it.

struct call size=2.. mutate=Shifting address=Unstable
  call.name_len                          offset=AbsoluteStatic(0x00) size=Fixed(1) align=Aligned(8) repr=MemoryIdentical atomic=AtomicWord
  call.name                              offset=AbsoluteStatic(0x01) size=Bounded(1, 32) align=Aligned(1) repr=MemoryIdentical atomic=AtomicWord mutate=Shifting
  call.args                              offset=Dynamic size=Unbounded align=Unaligned repr=MemoryIdentical atomic=AtomicWord mutate=Shifting address=Unstable

